using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;
namespace Society.Api;

public sealed record DocumentDesign {
 public int SchemaVersion{get;init;}=1;public double WidthMm{get;init;}=85.6;public double HeightMm{get;init;}=53.98;public double BleedMm{get;init;}=0;public double SafeMm{get;init;}=3;public string Background{get;init;}="#ffffff";public DesignElement[] Front{get;init;}=[];public DesignElement[] Back{get;init;}=[];
}
public sealed record DesignElement {
 public string Id{get;init;}="";public string Type{get;init;}="Text";public double X{get;init;}public double Y{get;init;}public double Width{get;init;}=30;public double Height{get;init;}=8;public double Rotation{get;init;}public double Opacity{get;init;}=1;public string Text{get;init;}="";public string Binding{get;init;}="";public bool Required{get;init;}public string Fill{get;init;}="#173e35";public string Stroke{get;init;}="#ffffff";public double StrokeWidth{get;init;}public double FontSize{get;init;}=4;public string Font{get;init;}="Vera";public bool Bold{get;init;}public string Align{get;init;}="left";public bool Locked{get;init;}public string Group{get;init;}="";public Guid? AssetId{get;init;}public string Fit{get;init;}="contain";public double CropX{get;init;}public double CropY{get;init;}public double CropWidth{get;init;}=1;public double CropHeight{get;init;}=1;public double ShadowBlur{get;init;}public string ShadowColor{get;init;}="#000000";public double ShadowX{get;init;}public double ShadowY{get;init;}
}
public sealed record CredentialSnapshot(DocumentDesign Design,Dictionary<string,string> Fields,Dictionary<string,Guid> Images);
public static class DesignSchema {
 public static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow};
 public static readonly string[] Fields=["member.full_name","member.photo","member.member_id","member.membership_category","member.joining_date","member.expiry_date","member.current_role","chapter.name","chapter.logo","region.name","society.name","society.logo","card.issue_date","card.expiry_date","card.serial_number","card.qr_code","event.name","project.name","certificate.title","certificate.reason","volunteer.verified_hours"];
 public static DocumentDesign Parse(string json){if(json.Length>150000)throw new DomainException("Template exceeds 150 KB");var d=JsonSerializer.Deserialize<DocumentDesign>(json,Json)??throw new DomainException("Design is required");Validate(d);return d;}
 static bool Color(string? value)=>value!=null&&Regex.IsMatch(value,"^#[0-9a-fA-F]{6}$");
 public static void Validate(DocumentDesign d){if(d.Front==null||d.Back==null||d.SchemaVersion!=1||!double.IsFinite(d.WidthMm)||!double.IsFinite(d.HeightMm)||d.WidthMm is <20 or >600||d.HeightMm is <20 or >600||d.BleedMm is <0 or >10||d.SafeMm is <0 or >20||!Color(d.Background)||d.Front.Length is <1 or >150||d.Back.Length>150)throw new DomainException("Use schema 1, dimensions 20–600 mm, bleed 0–10 mm, safe margin 0–20 mm and 1–150 front elements");var ids=new HashSet<string>();foreach(var e in d.Front.Concat(d.Back)){if(e==null||new[]{e.Id,e.Type,e.Text,e.Binding,e.Fill,e.Stroke,e.Font,e.Align,e.Group,e.Fit,e.ShadowColor}.Any(v=>v==null))throw new DomainException("Design elements and their typed fields cannot be null");if(e.Type=="QR"&&e.Binding is not("" or "card.qr_code"))throw new DomainException("QR elements must bind to opaque card verification");double[] values=[e.X,e.Y,e.Width,e.Height,e.Rotation,e.Opacity,e.FontSize,e.StrokeWidth,e.CropX,e.CropY,e.CropWidth,e.CropHeight,e.ShadowBlur,e.ShadowX,e.ShadowY];if(values.Any(v=>!double.IsFinite(v))||e.Id.Length is <1 or >80||!ids.Add(e.Id)||e.Type is not("Text" or "Rect" or "Ellipse" or "Line" or "Image" or "QR" or "Barcode")||e.Width<=0||e.Height<=0||e.Width>1200||e.Height>1200||Math.Abs(e.X)>1200||Math.Abs(e.Y)>1200||Math.Abs(e.Rotation)>360||e.Opacity is <0 or >1||e.FontSize is <1 or >100||e.StrokeWidth is <0 or >10||e.ShadowBlur is <0 or >10||Math.Abs(e.ShadowX)>20||Math.Abs(e.ShadowY)>20||!Color(e.Fill)||!Color(e.Stroke)||!Color(e.ShadowColor)||e.Font!="Vera"||e.Align is not("left" or "center" or "right")||e.Fit is not("contain" or "cover")||e.CropX<0||e.CropY<0||e.CropWidth<=0||e.CropHeight<=0||e.CropX+e.CropWidth>1.00001||e.CropY+e.CropHeight>1.00001||e.Text.Length>2000||e.Group.Length>80)throw new DomainException("Invalid design element: "+e.Id);if(e.Binding!=""&&!Fields.Contains(e.Binding))throw new DomainException("Unknown field binding: "+e.Binding);foreach(Match m in Regex.Matches(e.Text,@"\{\{([^{}]+)\}\}"))if(!Fields.Contains(m.Groups[1].Value.Trim()))throw new DomainException("Unknown typed placeholder: "+m.Value);if(Regex.Replace(e.Text,@"\{\{[^{}]+\}\}","").Contains("{{"))throw new DomainException("Invalid placeholder syntax");if(e.Type=="Image"&&e.AssetId==null&&e.Binding is not("member.photo" or "society.logo" or "chapter.logo"))throw new DomainException("Image must reference a private uploaded asset or approved image binding");}}
 public static string Resolve(DesignElement e,Dictionary<string,string> fields){if(e.Binding!="")return fields.GetValueOrDefault(e.Binding,"");return Regex.Replace(e.Text,@"\{\{([^{}]+)\}\}",m=>fields.GetValueOrDefault(m.Groups[1].Value.Trim(),""));}
 public static DocumentDesign Starter(string kind){bool card=kind=="Card";return new(){WidthMm=card?85.6:297,HeightMm=card?53.98:210,Front=[new(){Id="brand",Type="Rect",Width=card?85.6:297,Height=card?15:30,Fill="#12695a"},new(){Id="society",X=6,Y=5,Width=card?73:280,Height=10,Text="{{society.name}}",Fill="#ffffff",FontSize=card?4:8,Bold=true,Required=true},new(){Id="title",X=card?6:30,Y=card?22:65,Width=card?73:237,Height=card?9:22,Text=card?"{{member.full_name}}":"Certificate of appreciation",FontSize=card?5:13,Bold=true,Required=true,Align=card?"left":"center"},new(){Id="member",X=card?6:30,Y=card?33:105,Width=card?53:237,Height=card?6:18,Text=card?"{{member.member_id}}":"{{member.full_name}}",FontSize=card?3:9,Required=true,Align=card?"left":"center"},new(){Id="chapter",X=card?6:30,Y=card?41:138,Width=card?53:237,Height=10,Text="{{chapter.name}}",FontSize=card?3:6,Align=card?"left":"center"},new(){Id="qr",Type="QR",X=card?65:252,Y=card?32:166,Width=card?15:25,Height=card?15:25,Fill="#173e35"}],Back=card?[new(){Id="back-title",X=6,Y=6,Width=73,Height=10,Text="Membership verification",Bold=true,FontSize=4},new(){Id="back-serial",X=6,Y=20,Width=73,Height=8,Text="{{card.serial_number}}",FontSize=3},new(){Id="back-expiry",X=6,Y=33,Width=73,Height=7,Text="Valid through {{card.expiry_date}}",FontSize=3},new(){Id="back-note",X=6,Y=43,Width=73,Height=8,Text="Scan the QR code to check current validity.",FontSize=2.5}]:[]};}
}
